package com.edam.common.api;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/**
 * Durable idempotency storage (Module O).
 *
 * <p>Lookups are scoped by {@code (keyHash, operationType, actorId)} so a key generated by one
 * authenticated user can never collide with or replay another's response. The unique index on
 * those three columns is the concurrency arbiter: whichever transaction wins the INSERT proceeds;
 * the loser receives {@code PRECONDITION_FAILED} and should retry.
 */
public interface IdempotencyRecordRepository extends JpaRepository<IdempotencyRecord, UUID> {

	@Query("""
			select r from IdempotencyRecord r
			where r.keyHash       = :keyHash
			  and r.operationType = :operationType
			  and r.actorId       = :actorId
			""")
	Optional<IdempotencyRecord> findByKey(@Param("keyHash") String keyHash,
			@Param("operationType") String operationType,
			@Param("actorId") UUID actorId);

	@Modifying
	@Query("delete from IdempotencyRecord r where r.expiresAt < :cutoff")
	int deleteExpired(@Param("cutoff") Instant cutoff);

}
